# GENERATED by 'devil export gemini' from the kit's Claude-format sources. Do not edit; run 'devil export gemini' instead.
"""session.py: SessionStart hands over the briefing; PreCompact names what must
survive compaction.
"""

import json
import os
import re
import sys
import urllib.request
from pathlib import Path

from kit import PLUGIN_ROOT, host_root
from process import run
from respond import context, emit

# Where setup.sh stamps the version of the rules it seeded, and where the
# plugin's own version lives (A12: one version source).
STAMP = ".claude/rules/devil/.version"
PLUGIN_JSON = ".claude-plugin/plugin.json"
# Where `devil route on` (tools/route.sh) points a project at a local Switchyard.
ROUTED = ".claude/settings.local.json"
LOOPBACK = re.compile(r"http://127\.0\.0\.1:[0-9]{1,5}")


def _stamp_version():
    """The version the host's seeded rules were written by, or "" if unseeded."""
    try:
        lines = (Path(host_root()) / STAMP).read_text().splitlines()
    except OSError:
        return ""
    return next((ln[8:].strip() for ln in lines if ln.startswith("version=")), "")


def _plugin_version():
    """The plugin's version of record, or "" when the manifest is unreadable."""
    try:
        manifest = json.loads((PLUGIN_ROOT / PLUGIN_JSON).read_text())
        return str(manifest["version"])
    except Exception:
        return ""


def rules_drift():
    """One line when the seeded rules predate the plugin, else "".

    A plugin cannot ship `.claude/rules/*.md`, so the host's rules are a copy
    that a plugin update leaves behind. Without this the agent enforces the rules
    of whichever version seeded them, and never learns the kit moved on.

    Caveat: the stamp's version is read as a string, never resolved, so a host
    on a fork with its own `.version`, or one seeded in a layout whose stamp is
    not at this path, is compared against this plugin's manifest and reported as
    drift, or read as unseeded and reported as nothing. It is a warning, never a
    gate: the direction it is wrong in is "no warning".
    """
    old, new = _stamp_version(), _plugin_version()
    if not old or not new or old == new:
        return ""
    return (
        f"seeded devil rules are from {old}, plugin is {new}: run /devil:setup --apply"
    )


def session_start(data):
    """Hand over the briefing rather than making the agent re-derive it.

    digest.sh is cached and fingerprinted to git state, so this is a file read
    on every session after the first (rules/memory.md: prefer a tool that cannot
    go stale over a memory that can).
    """
    # A flow's review step is a nested `claude -p` that gets its context from the
    # flow; a briefing here would only cost tokens it was never meant to read.
    if os.environ.get("DEVIL_FLOW_CHILD") == "1":
        sys.exit(0)
    parts = []
    preamble = ""
    digest = PLUGIN_ROOT / "tools" / "digest.sh"
    if digest.is_file():
        # The digest describes the host project, so it runs there.
        rc, out = run(["bash", str(digest)], cwd=host_root())
        # Caveat: the briefing is cut at 4000 characters, so a long digest loses
        # its last sections (untested, duplication) silently; `devil digest`
        # prints the whole of it.
        if rc == 0 and out:
            preamble = (
                f"Project briefing from `{digest}` (cached, fingerprinted to "
                "git state; no need to re-derive it):\n\n"
            )
            parts.append(out[:4000])
    drift = rules_drift()
    # The drift line rides along with the briefing, and is delivered on its own
    # when there is no briefing: re-seeding the rules is the point of this hook.
    if drift:
        parts.append(drift)
    if parts:
        context("SessionStart", preamble + "\n\n".join(parts))
    sys.exit(0)


def _routed_url():
    """The loopback proxy this project is routed through, or "" if it is not routed."""
    try:
        cfg = json.loads((Path(host_root()) / ROUTED).read_text())
    except (OSError, ValueError):
        return ""
    env = cfg.get("env") if isinstance(cfg, dict) and "_devilRoute" in cfg else None
    url = env.get("ANTHROPIC_BASE_URL") if isinstance(env, dict) else None
    return url if isinstance(url, str) and LOOPBACK.fullmatch(url) else ""


def _healthy(url):
    # No proxy handler: an HTTP(S)_PROXY in the environment must not carry a
    # loopback probe off the machine.
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    try:
        with opener.open(url + "/health", timeout=2) as resp:
            return resp.status == 200
    except Exception:
        return False


def route_guard(data):
    """Turn routing off when the proxy this project points at is down.

    It runs as its own synchronous SessionStart hook. This session already sends
    every call to that proxy, so every call fails and Claude can be told nothing;
    only a synchronous hook's systemMessage reaches the user. Turning routing off
    here is what lets the next start talk to Anthropic directly.
    """
    # Exported kits (codex, copilot) carry this hook but no tools/: those hosts
    # never read ANTHROPIC_BASE_URL, so a project routed for Claude Code is not
    # theirs to fix.
    route = PLUGIN_ROOT / "tools" / "route.sh"
    url = _routed_url() if route.is_file() else ""
    if not url or _healthy(url):
        sys.exit(0)
    rc, out = run(["bash", str(route), "off"], cwd=host_root())
    if rc == 0:
        emit(
            {
                "systemMessage": f"Switchyard is down at {url}, so devil turned "
                "model routing off for this project. This session still points at "
                "it: restart claude. To route again: devil route start, then "
                "devil route on."
            }
        )
    why = out.splitlines()[-1] if out else f"exit {rc}"
    emit(
        {
            "systemMessage": f"Switchyard is down at {url}, and devil could not "
            f"turn routing off ({why}). Run devil route start, or fix "
            f"{ROUTED}, then restart claude."
        }
    )


def pre_compact(data):
    """Compaction drops detail. Say what is worth carrying across it.

    `/devil:handoff` is named here because a handoff document survives what a
    compaction cannot: another session, or another harness, starts from it.
    """
    context(
        "PreCompact",
        "Before compacting, preserve: measured numbers and the command that "
        "produced them, any `devil` verdict and its conditions, the current "
        "done-when, and anything still UNKNOWN. Per rules/memory.md, do NOT "
        "preserve what the kit's `tools/digest.sh` re-derives; re-run it after "
        "compaction instead of carrying a copy that will be stale. If this work "
        "has to continue in a new session, run `/devil:handoff` first: it writes "
        "a portable document of pointers (redacted) and ends with the return "
        "block, which is what survives; compaction keeps the rest in this "
        "session only.",
    )
